#include <cuda_runtime.h>
#include <chrono>
#include <cstdlib>
#include "study_support.h"
#include "../allreduce-cuda/collectives.cu"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}while(0)
struct Case{int n;float *ri,*ro,*rt;std::vector<float>x;};
void reset(Case&c){std::vector<float>i(c.n+128,-777),o(i.size(),-777),t((c.n+1)/2+128,-777);std::copy(c.x.begin(),c.x.end(),i.begin()+64);CK(cudaMemcpy(c.ri,i.data(),i.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.ro,o.data(),o.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.rt,t.data(),t.size()*4,cudaMemcpyHostToDevice));}
void ring(Case&c,int rank,cudaStream_t stream){int half=(c.n+1)/2,lens[2]={half,c.n-half},starts[2]={0,half};float*out=c.ro+64,*tmp=c.rt+64;study_mpi_lengths(c.n);CK(cudaMemcpyAsync(out,c.ri+64,c.n*4,cudaMemcpyDeviceToDevice,stream));CK(cudaStreamSynchronize(stream));int recv=1-rank,send=rank;study_mpi_scatter(tmp,lens[recv],out+starts[send],lens[send]);kernel_add<<<32,256,0,stream>>>(tmp,out+starts[recv],lens[recv],out+starts[recv]);CK(cudaGetLastError());CK(cudaStreamSynchronize(stream));send=1-rank;recv=rank;study_mpi_allgather(out+starts[recv],lens[recv],out+starts[send],lens[send]);CK(cudaDeviceSynchronize());}
int main(){try{char*e=getenv("OMPI_COMM_WORLD_LOCAL_RANK");if(!e)throw std::runtime_error("missinglocalrank");int rank=atoi(e);CK(cudaSetDevice(rank));cudaStream_t stream;CK(cudaStreamCreate(&stream));if(study_mpi_start()!=rank)throw std::runtime_error("rankmapping");std::vector<Case>cs;for(int n:sizes()){Case c;c.n=n;c.x=fixture(n,rank);CK(cudaMalloc(&c.ri,(n+128)*4));CK(cudaMalloc(&c.ro,(n+128)*4));CK(cudaMalloc(&c.rt,((n+1)/2+128)*4));reset(c);ring(c,rank,stream);cs.push_back(c);}for(int trial=1;trial<=5;trial++){study_mpi_guard();std::vector<float>out;if(rank==0)out.push_back(6);for(auto&c:cs){reset(c);std::vector<float>x(c.n),both(2*c.n);CK(cudaMemcpy(x.data(),c.ri+64,c.n*4,cudaMemcpyDeviceToHost));study_mpi_capture(x.data(),c.n,both.data());if(rank==0){out.push_back(c.n);out.insert(out.end(),both.begin(),both.end());}}double sec=0;for(auto&c:cs){study_mpi_guard();study_mpi_barrier();auto start=std::chrono::steady_clock::now();for(int r=0;r<3;r++)ring(c,rank,stream);double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();sec+=study_mpi_max(elapsed);auto capture=[&](float*ptr,int n){std::vector<float>x(n),both(2*n);CK(cudaMemcpy(x.data(),ptr,n*4,cudaMemcpyDeviceToHost));study_mpi_capture(x.data(),n,both.data());if(rank==0)out.insert(out.end(),both.begin(),both.end());};capture(c.ro+64,c.n);capture(c.rt+64,(c.n+1)/2);std::vector<float>guards;for(auto a:std::vector<std::pair<float*,int>>{{c.ri,c.n},{c.ro,c.n},{c.rt,(c.n+1)/2}}){std::vector<float>raw(a.second+128);CK(cudaMemcpy(raw.data(),a.first,raw.size()*4,cudaMemcpyDeviceToHost));guards.insert(guards.end(),raw.begin(),raw.begin()+64);guards.insert(guards.end(),raw.end()-64,raw.end());if(a.first==c.ri&&memcmp(raw.data()+64,c.x.data(),c.n*4))throw std::runtime_error("readonlyinput");}std::vector<float>allguards(768);study_mpi_capture(guards.data(),384,allguards.data());if(rank==0)out.insert(out.end(),allguards.begin(),allguards.end());study_mpi_guard();}if(rank==0){std::string path="trial"+std::to_string(trial)+".bin";std::ofstream o(path,std::ios::binary);o.write((char*)out.data(),out.size()*4);o.close();double met[2];if(study_check(path.c_str(),met))throw std::runtime_error("fulloracle");printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum6_max2rank_preallocated_source_ring_MPI_reduce_allgather_context_complete\",\"jit_excluded\":true,\"internal_repeats\":18,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,sec,out.size(),path.c_str(),out.size());fflush(stdout);}study_mpi_barrier();}for(auto&c:cs){cudaFree(c.ri);cudaFree(c.ro);cudaFree(c.rt);}cudaStreamDestroy(stream);study_mpi_finish();return 0;}catch(std::exception&e){fprintf(stderr,"%s\n",e.what());study_mpi_abort();return 1;}}
